		<div class="elementor-element elementor-element-9386d96 e-flex e-con-boxed e-con e-parent" data-id="9386d96" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
